                    Value = box this.Hierarchy
                    ProviderDbType = Some "SqlHierarchyId" } ]

    let HierarchyIdSupport = table<HierarchyIdSupport>

    [<CLIMutable>]
    type NullableKeyUpsert =
        { [<ProviderDbType("UniqueIdentifier")>]
          mutable Key1: System.Guid
          [<ProviderDbType("NVarChar")>]
          mutable Key2: string
          [<ProviderDbType("NVarChar")>]
          mutable Value: string }

        interface IWriteColumns with
            member this.WriteColumns =
                [ { WriteColumn.Name = "Key1"
                    Value = box this.Key1
                    ProviderDbType = Some "UniqueIdentifier" }
                  { WriteColumn.Name = "Key2"
                    Value = box this.Key2
                    ProviderDbType = Some "NVarChar" }
                  { WriteColumn.Name = "Value"
                    Value = box this.Value
                    ProviderDbType = Some "NVarChar" } ]

    let NullableKeyUpsert = table<NullableKeyUpsert>



type QueryContextFactory =
    { OpenContext: unit -> QueryContext
      OpenContextAsync: unit -> System.Threading.Tasks.Task<QueryContext> }
    // This provider holds no factory-level resources; each connection is owned and disposed by its QueryContext.
    member _.Dispose() = ()

    interface System.IDisposable with
        member this.Dispose() = this.Dispose()

    interface IQueryContextFactory with
        member this.OpenContextAsync() = this.OpenContextAsync()

    static member Create(connectionString: string, ?sqlLogger) =
        let emitter = SqlHydra.Query.SqlServerEmitter()

        let createConn () : System.Data.Common.DbConnection =
            new Microsoft.Data.SqlClient.SqlConnection(connectionString)

        let openContext () =
            let conn = createConn ()
            conn.Open()
            let ctx = new QueryContext(conn, emitter)
            sqlLogger |> Option.iter (fun logger -> ctx.Logger <- logger)
            ctx

        let openContextAsync () =
            task {
                let conn = createConn ()
                do! conn.OpenAsync()
                let ctx = new QueryContext(conn, emitter)
                sqlLogger |> Option.iter (fun logger -> ctx.Logger <- logger)
                return ctx
            }

        { OpenContext = openContext
          OpenContextAsync = openContextAsync }
